<script setup>
/**
 * PostCard.vue - 社区帖子卡片
 * 
 * 展示内容:
 * - 帖子标题
 * - 作者头像和名称
 * - 分类标签
 * - 内容摘要
 * - 点赞数 / 评论数
 * 
 * Props:
 * - post: object - 帖子数据对象
 *   { id, title, author, avatar, category, content, likes, comments, views, createdAt, isHot }
 */

defineProps({
  post: {
    type: Object,
    required: true
  }
})

// 格式化日期
const formatDate = (dateStr) => {
  if (!dateStr) return ''
  const date = new Date(dateStr)
  if (isNaN(date.getTime())) return dateStr
  const now = new Date()
  const diff = (now - date) / 1000
  if (diff < 60) return '刚刚'
  if (diff < 3600) return Math.floor(diff / 60) + '分钟前'
  if (diff < 86400) return Math.floor(diff / 3600) + '小时前'
  if (diff < 604800) return Math.floor(diff / 86400) + '天前'
  return `${date.getMonth() + 1}月${date.getDate()}日`
}
</script>

<template>
  <div class="post-card" v-if="post">
    <!-- 热门标签 -->
    <div v-if="post.isHot" class="hot-badge">🔥 热门</div>

    <!-- 头部: 作者信息 -->
    <div class="card-header">
      <img
        :src="post.avatar || '/images/avatar-placeholder.jpg'"
        :alt="post.author"
        class="author-avatar"
        loading="lazy"
      />
      <div class="author-info">
        <span class="author-name">{{ post.author }}</span>
        <span class="post-time">{{ formatDate(post.createdAt) }}</span>
      </div>
      <span class="category-tag">{{ post.category }}</span>
    </div>

    <!-- 标题 -->
    <h3 class="post-title">{{ post.title }}</h3>

    <!-- 内容摘要 -->
    <p class="post-content">
      {{ post.content ? post.content.substring(0, 100) + '...' : '' }}
    </p>

    <!-- 底部统计 -->
    <div class="card-footer">
      <div class="stat-item">
        <span class="stat-icon">❤️</span>
        <span class="stat-count">{{ post.likes || 0 }}</span>
      </div>
      <div class="stat-item">
        <span class="stat-icon">💬</span>
        <span class="stat-count">{{ post.comments || 0 }}</span>
      </div>
      <div class="stat-item">
        <span class="stat-icon">👁️</span>
        <span class="stat-count">{{ post.views || 0 }}</span>
      </div>
    </div>
  </div>
</template>

